BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('g-kentei-k-q1', '8. AIに必要な数理・統計知識',
   'コインを10回投げて表が出る回数のように、「成功か失敗かの2択」の試行をN回繰り返したときの成功回数が従う確率分布はどれか。',
   NULL::text,
   '["二項分布（Binomial Distribution）", "正規分布（Normal Distribution）", "一様分布（Uniform Distribution）", "ポアソン分布（Poisson Distribution）"]',
   0, '[0]', 'single',
   '{"asked":"成功/失敗の2択試行をN回繰り返したときの成功回数が従う確率分布を選ぶ問題。","why_asked":"確率分布の名前と「何を数えているか」を対応づけられるかは数理分野の基本の基本。","kid":"二項分布は「当たるか外れるかの2択のクジをN回引いたとき、当たりが何回出るか」を表す確率分布。コイン投げやアンケートのYES/NOのように、結果が2つしかない試行を繰り返す場面で登場する。","eg":"たとえるなら、コインを10回投げて表が何回出るかを何度も繰り返し記録し、その回数ごとの出やすさをグラフにしたもの。3回や5回あたりが山になり、0回や10回はめったに起きない、という形になる。","terms":[["二項分布","成功確率pの試行をN回繰り返したときの成功回数が従う確率分布"],["ベルヌーイ試行","結果が成功か失敗かの2通りしかない、1回だけの試行"]],"think":"「2択の試行を繰り返す」「その成功回数を数える」という2点が二項分布のキーワード。1回だけの2択ならベルヌーイ試行、それをN回繰り返した合計の分布が二項分布になる。","vs":"正規分布と混同しやすいが、正規分布は連続的な量（身長や測定誤差など）が従う分布で、二項分布のように整数の回数だけを扱うものではない。実際には試行回数Nが大きいと二項分布は正規分布に近づいていく。","opt":["正解。成功/失敗の2択試行をN回繰り返したときの成功回数が従う確率分布。","正規分布は連続的な量が釣鐘型に散らばる分布で、離散的な成功回数を数える二項分布とは形も対象も異なる。","一様分布はどの値も同じ確率で起こる分布で、成功回数のように山ができる二項分布とは異なる。","ポアソン分布は一定時間内に稀な出来事が起こる回数を表す分布で、決まった回数Nの試行を繰り返す二項分布とは前提が異なる。"]}'),

  ('g-kentei-k-q2', '8. AIに必要な数理・統計知識',
   'ある製品の不良品が出る確率は0.3で、10個の製品を検査するとする。この10個のうち不良品が出る個数の「期待値（平均して何個か）」はいくつか。',
   NULL::text,
   '["3個", "0.3個", "7個", "10個"]',
   0, '[0]', 'single',
   '{"asked":"二項分布の期待値を、試行回数と成功確率から計算する問題。","why_asked":"二項分布の期待値の公式Np自体はシンプルだが、暗記だけで終わらせず実際に数値を当てはめられるかを確認する定番の計算問題。","kid":"二項分布の期待値は「試行の回数×1回あたりの成功確率」で計算できる。10個検査して、1個あたり不良品が出る確率が0.3なら、平均して10×0.3個の不良品が出ると見込まれる。","eg":"たとえるなら、10本のくじのうち3割の確率で当たりが出るとしたら、10本引けば平均して3本くらい当たりが出るだろう、という素朴な見積もり。","terms":[["期待値","平均して見込まれる値。二項分布ではN×pで計算できる"],["N（試行回数）とp（成功確率）","二項分布を決める2つのパラメータ"]],"calc":{"steps":["問題: 試行回数N=10、成功確率p=0.3のとき、期待値を求める","ステップ1: 二項分布の期待値の公式は「N×p」","ステップ2: 数値を当てはめる。10 × 0.3","ステップ3: 掛け算する。10 × 0.3 = 3","答え: 期待値は3個"],"formula":"期待値 E[X] = N × p = 10 × 0.3 = 3"},"think":"二項分布の期待値はN×pという掛け算だけで求まる。10回の試行のうち平均して何回成功するかを知りたいときは、試行回数に成功確率を掛けるだけでよい。","vs":"確率0.3をそのまま個数と間違えて「0.3個」と答えないよう注意。0.3は1回あたりの確率であり、10回分を掛け合わせて初めて期待される個数になる。","opt":["正解。N×p=10×0.3=3個。","0.3は1個あたりの不良品が出る確率であり、10個分の期待値ではない。","10-0.3×10を7と誤って計算した値であり、期待値の公式とは異なる計算。","10個すべて検査するという試行回数そのものであり、不良品の期待値ではない。"]}'),

  ('g-kentei-k-q3', '8. AIに必要な数理・統計知識',
   '正規分布の山の形（グラフの見た目）は、何によって決まるか。最も適切なものを選べ。',
   NULL::text,
   '["平均と分散（または標準偏差）の2つの値だけで完全に決まる", "データの件数（サンプルサイズ）だけで完全に決まる", "最大値と最小値の2つの値だけで完全に決まる", "中央値と最頻値の2つの値だけで完全に決まる"]',
   0, '[0]', 'single',
   '{"asked":"正規分布のグラフの形を決めるパラメータが何かを問う問題。","why_asked":"正規分布は「平均と分散さえ分かれば形が1つに定まる」という性質が、統計モデルを扱う上での基本の前提になる。","kid":"正規分布は左右対称の釣鐘型の山だけど、その山の「真ん中の位置」と「山の幅の広さ」の2つの数字さえ決めれば、形がぴったり1つに定まる。真ん中の位置を決めるのが平均、幅の広さを決めるのが分散（標準偏差）。","eg":"たとえるなら、テントを立てるとき「支柱を立てる場所（平均）」と「テントの裾をどれだけ広げるか（分散）」の2つさえ決まれば、テントの形がそのまま1つに決まる、というイメージ。","terms":[["平均","正規分布の山の頂点（真ん中）の位置を決める値"],["分散・標準偏差","正規分布の山がどれだけ横に広がっているか（幅）を決める値"]],"think":"正規分布は「平均μ、分散σ²」という2つの数字だけで式が完全に書ける、という性質を押さえる。他の分布（例えば実際のデータのヒストグラム）は形を決めるのにもっと多くの情報が要るが、正規分布は理想化された形なのでこの2つだけで十分。","vs":"最大値・最小値や中央値・最頻値と混同しやすいが、これらは正規分布の形を決める公式のパラメータには含まれない。正規分布では平均と中央値と最頻値はすべて同じ値（山の頂点）に一致する。","opt":["正解。平均が山の位置、分散（標準偏差）が山の幅を決め、この2つだけで形が完全に定まる。","データの件数はヒストグラムの精度には関わるが、理想化された正規分布の形そのものを決めるパラメータではない。","最大値と最小値は正規分布の式には登場せず、理論上は正規分布の裾は無限に続くため形を決める値にはならない。","正規分布では中央値・最頻値は平均と同じ値になるため、別の独立したパラメータとして形を決めるものではない。"]}'),

  ('g-kentei-k-q4', '8. AIに必要な数理・統計知識',
   '平均が同じ2つの正規分布のうち、標準偏差が大きい方のグラフの形はどうなるか。',
   NULL::text,
   '["山の高さが低くなり、横に広がった、なだらかな形になる", "山の高さが高くなり、横に狭まった、とがった形になる", "山の位置（頂点の横の位置）が右にずれる", "山の形は標準偏差の大小に関係なくまったく変わらない"]',
   0, '[0]', 'single',
   '{"asked":"標準偏差の大小が正規分布のグラフの形にどう影響するかを問う問題。","why_asked":"「標準偏差＝散らばりの大きさ」という定義を、グラフの見た目という視覚的な理解に結びつけられるかを問う。","kid":"標準偏差は「データが平均からどれくらい離れて散らばっているか」を表す数字。標準偏差が大きいと、データが平均から遠くまで散らばっているということなので、グラフは横に広がってなだらかな山になる。逆に標準偏差が小さいと、データが平均のすぐ近くに集まるので、山は狭くとがった形になる。","eg":"たとえるなら、的当てで矢が中心（平均）の近くに集まればとがった山、矢があちこちに散らばれば低く広がった山になる、というイメージ。散らばりが大きいほど山は低く横に伸びる。","terms":[["標準偏差","データが平均からどれくらい離れて散らばっているかを表す値。大きいほど散らばりが大きい"],["面積が常に1","正規分布のグラフの下側の面積は必ず1になるため、横に広がると高さは低くなる"]],"think":"正規分布のグラフの下の面積は常に1（100%）と決まっている。標準偏差が大きくデータが横に広く散らばると、その面積1を横に引き伸ばして保つために、山の高さは低くなる。逆に散らばりが小さいと、面積1を狭い範囲に集めるために山は高くとがる。","vs":"平均と混同しやすいが、平均は山の位置（左右の場所）を決め、標準偏差は山の広がり方（幅と高さ）を決める。今回は平均が同じ設定なので、山の位置は動かず、広がり方だけが変わる。","opt":["正解。標準偏差が大きいほどデータの散らばりが大きく、山は横に広がりなだらかになる。","標準偏差が大きいほど散らばりは大きくなるため、山がとがって狭まるという記述は逆になっている。","平均が同じという前提なので、標準偏差の大小によって山の位置（頂点の横の場所）は動かない。","標準偏差はグラフの広がり方を直接決める値であり、大小によって山の形は変化する。"],"viz":"<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">標準偏差の違いと山の形</text><line x1=\"30\" y1=\"115\" x2=\"310\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><path d=\"M 30 115 Q 170 20 310 115\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><path d=\"M 90 115 Q 170 55 250 115\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\"/><circle cx=\"170\" cy=\"115\" r=\"2.5\" fill=\"#e8eaf0\"/><text x=\"170\" y=\"128\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">平均（同じ位置）</text><text x=\"60\" y=\"95\" font-size=\"9\" fill=\"#60a5fa\">標準偏差 大</text><text x=\"200\" y=\"70\" font-size=\"9\" fill=\"#c9a04a\">標準偏差 小</text></svg>"}'),

  ('g-kentei-k-q5', '8. AIに必要な数理・統計知識',
   'サイコロの出目（1〜6）のように、決まった範囲の中でどの値も同じ確率で起こる確率分布はどれか。',
   NULL::text,
   '["一様分布（Uniform Distribution）", "正規分布（Normal Distribution）", "二項分布（Binomial Distribution）", "ポアソン分布（Poisson Distribution）"]',
   0, '[0]', 'single',
   '{"asked":"どの値も同じ確率で起こる分布の名前を選ぶ問題。","why_asked":"「一様」という言葉の意味どおり、確率分布の中でも最も単純な形として名前と性質を対応づけているか問う基本問題。","kid":"一様分布は「どの結果も同じくらい起こりやすい」分布。サイコロなら1〜6のどの目も6分の1ずつで同じ確率、というのが典型例。グラフにすると、山や谷がなく、真横に平らな形になる。","eg":"たとえるなら、くじ引きの箱に1〜6の番号が同じ枚数ずつ入っていて、どの番号を引く確率も同じ、というイメージ。特にどれかが出やすい、ということがない。","terms":[["一様分布","決まった範囲の中で、どの値も同じ確率で起こる確率分布"],["確率密度","一様分布のグラフでは、範囲全体にわたって高さが一定になる"]],"think":"「どれも同じ確率」というキーワードがそのまま一様分布を指す。正規分布のような山型や、二項分布のような偏りがなく、グラフが平らな長方形（連続の場合）や、同じ高さの棒が並ぶ形（離散の場合）になる点が特徴。","vs":"正規分布と混同しやすいが、正規分布は平均の近くが最も起こりやすく、離れるほど確率が下がる山型である一方、一様分布はどこも同じ高さで山ができない点が違う。","opt":["正解。決まった範囲の中でどの値も同じ確率で起こる、平らな形の確率分布。","正規分布は平均付近が最も起こりやすい山型の分布で、すべての値が同じ確率になる一様分布とは形が異なる。","二項分布は2択の試行をN回繰り返した成功回数の分布で、単一の値がどれも同じ確率という一様分布とは前提が異なる。","ポアソン分布は稀な出来事が起こる回数の分布で、値によって起こりやすさが変わるため、一様分布とは異なる。"]}'),

  ('g-kentei-k-q6', '8. AIに必要な数理・統計知識',
   '「雨が降っている」という条件のもとで「傘を持っている人の割合」を求めるように、ある出来事が起きたという条件のもとで、別の出来事が起きる確率を何と呼ぶか。',
   NULL::text,
   '["条件付き確率", "同時確率", "周辺確率", "事前確率"]',
   0, '[0]', 'single',
   '{"asked":"ある条件のもとで別の出来事が起こる確率の名前を問う問題。","why_asked":"ベイズの定理を理解する前提として、条件付き確率という考え方そのものを押さえているか確認する基本問題。","kid":"条件付き確率は「〜という状況のときに限って」という条件を先に決めてから、その中でどれくらいの確率で起こるかを考えるもの。「雨の日に限って、傘を持っている人はどれくらいいるか」というふうに、対象を絞り込んでから確率を求める。","eg":"たとえるなら、クラス全体ではなく「今日休んだ人」という条件で絞り込んでから、「その中で風邪の人は何割か」を求めるようなイメージ。母集団そのものを条件で絞り込んでいる点がポイント。","terms":[["条件付き確率","ある出来事Bが起きたという条件のもとで、出来事Aが起きる確率。P(A|B)と書く"],["同時確率","2つの出来事が両方とも起きる確率。P(A∩B)と書く"]],"think":"「〜のとき」「〜という条件で」という言い回しが出たら条件付き確率を疑う。全体の中の確率ではなく、条件で絞り込んだ範囲の中だけで確率を考え直す、という点が通常の確率との違い。","vs":"同時確率と混同しやすいが、同時確率は「両方とも起こる確率」を全体に対する割合で求めるのに対し、条件付き確率は「片方が起きたという前提のもとで」もう片方が起こる割合を求める点が違う。","opt":["正解。ある出来事が起きたという条件のもとで、別の出来事が起きる確率。","同時確率は2つの出来事が両方とも起こる確率を、全体に対する割合として求めるもので、条件で絞り込むものではない。","周辺確率は他の変数の値によらず、1つの出来事だけに着目した単純な確率のことで、条件付けは行わない。","事前確率はベイズの定理で、新しい証拠を得る前に持っていたもともとの確率のことで、条件付き確率そのものの名称ではない。"]}'),

  ('g-kentei-k-q7', '8. AIに必要な数理・統計知識',
   'ある病気にかかっている人の割合は全体の1%である。この病気の検査は、病気の人を90%の確率で正しく「陽性」と判定し、病気でない人も90%の確率で正しく「陰性」と判定する。ある人が検査で「陽性」と判定されたとき、実際にその人が病気である確率（ベイズの定理で計算）に最も近いものはどれか。',
   NULL::text,
   '["約8%", "約90%", "約1%", "約99%"]',
   0, '[0]', 'single',
   '{"asked":"ベイズの定理を使って、検査陽性という条件のもとで実際に病気である確率を計算する問題。","why_asked":"「検査の精度90%＝陽性なら90%の確率で病気」という直感的な誤解を、実際の数値計算で正すための定番論点。","kid":"病気の人はもともと100人に1人しかいない。検査で「陽性」と出る人の中には、①本当に病気で正しく陽性と出た人と、②病気ではないのに間違って陽性と出てしまった人の2種類が混ざっている。病気でない99人の側からも1割（約10人）が間違って陽性になるので、陽性と出た人の中では「間違って陽性になった健康な人」の方がずっと多くなり、本当に病気である確率は意外と低くなる。","eg":"たとえるなら、1000人の教室で、本当にカンニングした人は10人しかいないのに、疑わしい行動（陽性）をとった人が100人近くいたら、その100人の中で本当にカンニングした人はごく一部しかいない、というイメージ。母数の違いが結果を大きく左右する。","terms":[["ベイズの定理","事前確率と新しい証拠（検査結果）から、事後確率を計算する公式"],["事前確率","検査を受ける前の、もともとの病気にかかっている確率（1%）"]],"calc":{"steps":["問題: 1000人のうち病気の人は1%＝10人、健康な人は990人とする","ステップ1: 病気の人10人のうち、90%が正しく陽性になる。10 × 0.9 = 9人（本当に病気で陽性）","ステップ2: 健康な人990人のうち、10%が間違って陽性になる。990 × 0.1 = 99人（健康なのに陽性）","ステップ3: 陽性と判定された人の合計は 9 + 99 = 108人","ステップ4: そのうち本当に病気なのは9人なので、病気である確率は 9 ÷ 108 ≈ 0.083","答え: 約8%"],"formula":"P(病気|陽性) = 9 ÷ (9+99) = 9/108 ≈ 0.083 → 約8%"},"think":"検査の精度（90%）だけを見ると病気だと思い込みやすいが、病気の人がもともと少ない（1%）ため、健康な人からの誤判定（99人）が本当に病気の人（9人）を数で大きく上回ってしまう。この「もともとの少なさ」を考慮するのがベイズの定理の役割。","vs":"「検査の精度が90%だから、陽性なら90%の確率で病気」という誤解に注意。それは病気の人が陽性になる確率であって、陽性になった人が病気である確率（今回求めたい値）とは向きが逆で、もともとの病気の割合（事前確率）を反映していない。","opt":["正解。9÷(9+99)≈0.083で、約8%になる。","検査が病気の人を正しく陽性と判定する確率（感度）であり、陽性になった人が実際に病気である確率とは向きが逆の数値。","病気にかかっている人のもともとの割合（事前確率）であり、検査結果を反映した後の確率ではない。","陽性のうち健康な人の割合を1から引いた大まかな見積もりで、正しいベイズの計算結果ではない。"]}'),

  ('g-kentei-k-q8', '8. AIに必要な数理・統計知識',
   'コインを投げる前は「表か裏か半々で予測しづらい」が、投げた後に「表だった」と分かれば予測の不確かさは無くなる。この「出来事がどれくらい予測しにくいか（不確かさ）」を数値で表す情報理論の概念はどれか。',
   NULL::text,
   '["エントロピー（情報量）", "分散", "期待値", "尤度"]',
   0, '[0]', 'single',
   '{"asked":"出来事の予測しにくさ（不確かさ）を数値化する情報理論の概念を選ぶ問題。","why_asked":"損失関数の交差エントロピーの土台になる考え方で、G検定でも情報理論の基礎として問われやすい。","kid":"エントロピーは「結果がどれくらい予測しづらいか」を数字で表したもの。表と裏がちょうど半々で出るコインは「次に何が出るか全く読めない」ので不確かさ（エントロピー）が大きい。逆に、ほとんど表しか出ないようないかさまコインは「たぶん表だろう」と予測しやすいので、エントロピーは小さくなる。","eg":"たとえるなら、天気予報で「明日は50%の確率で雨」と言われるとどちらとも判断がつかず不安（エントロピーが大きい）だが、「明日は99%の確率で晴れ」と言われればほぼ確信できて安心する（エントロピーが小さい）、というイメージ。","terms":[["エントロピー（情報量）","出来事の起こりやすさのばらつき方から、予測のしにくさ（不確かさ）を数値化したもの"],["確率が偏っている","特定の結果が起こりやすく、予測しやすい状態。エントロピーは小さくなる"]],"think":"「予測のしやすさ」と「エントロピーの大小」は逆の関係にある。予測しやすい（結果が偏っている）ほどエントロピーは小さく、予測しにくい（結果が均等にばらけている）ほどエントロピーは大きくなる、という向きを押さえる。","vs":"分散と混同しやすいが、分散は数値データの散らばりの大きさを測るのに対し、エントロピーは確率分布そのものの「予測のしにくさ」を測るもので、対象にしているものが違う。","opt":["正解。出来事の予測しにくさ（不確かさ）を数値化した情報理論の概念。","分散はデータが平均からどれだけ散らばっているかを数値データそのものについて測る指標で、確率分布の予測しにくさとは対象が異なる。","期待値は平均して見込まれる値を表す指標で、予測のしにくさそのものを表すものではない。","尤度はあるパラメータのもとで観測データがどれだけ起こりやすいかを表す値で、予測のしにくさを直接数値化したものではない。"]}'),

  ('g-kentei-k-q9', '8. AIに必要な数理・統計知識',
   'サイコロの出目のように取りうる結果が6通りある場合、エントロピー（不確かさ）が最大になるのはどのような確率分布のときか。',
   NULL::text,
   '["6つの目がすべて同じ確率（それぞれ6分の1）で出るとき", "1つの目だけが必ず出て、他の目は絶対に出ないとき", "6つの目のうち2つだけが交互に出るとき", "確率分布の形にかかわらず、エントロピーは常に一定である"]',
   0, '[0]', 'single',
   '{"asked":"取りうる結果が複数あるとき、エントロピーが最大になる確率分布の形を問う問題。","why_asked":"「均等に散らばっているほど不確かさが大きい」という情報理論の基本性質を、具体的な確率分布の形として理解しているか問う。","kid":"どの目が出るかまったく読めない、つまり全部の目が同じ確率で出るときが、一番「先が読めない」状態になる。逆に、ある目しか出ないと最初から分かっていれば、予測に迷う余地がなくエントロピーは0（不確かさ無し）になる。","eg":"たとえるなら、6人が同じくらいの実力で並んでいる大会は「誰が優勝するか全く読めない」（エントロピー最大）けれど、1人が圧倒的に強ければ「その人がほぼ確実に優勝する」（エントロピー小さい）、というイメージ。","terms":[["エントロピーの最大値","取りうる結果の数が同じなら、確率が均等に分かれているときにエントロピーは最大になる"],["確率が0か1に偏る","ある結果しか起こらないと分かっている状態。エントロピーは最小（0）になる"]],"think":"エントロピーは「予測のしにくさ」なので、確率が均等に散らばるほど大きくなり、逆にどれか1つに確率が集中するほど小さくなる。6通りの結果があるなら、すべてが6分の1ずつで一番「読めない」状態がエントロピーの最大値になる。","vs":"「結果の数が多いほどエントロピーが大きい」という誤解に注意。結果の数が同じでも、確率の偏り方によってエントロピーは変わり、均等であるほど大きく、偏っているほど小さくなる。","opt":["正解。6つの目がすべて同じ確率のとき、最も予測しにくくエントロピーが最大になる。","1つの目しか出ないと分かっている状態は、予測にまったく迷いがなくエントロピーは最小（0）になる。","2つの目に確率が集中し他の4つの目の確率が0に近い状態は、6つが均等な場合よりも予測しやすく、エントロピーは最大にはならない。","確率の偏り方によってエントロピーの値は変化するため、常に一定という記述は誤り。"],"viz":"<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">均等 vs 偏り：エントロピーの大小</text><text x=\"80\" y=\"34\" text-anchor=\"middle\" font-size=\"9\" fill=\"#60a5fa\">均等（エントロピー大）</text><rect x=\"35\" y=\"55\" width=\"14\" height=\"45\" fill=\"#3b82f6\"/><rect x=\"55\" y=\"55\" width=\"14\" height=\"45\" fill=\"#3b82f6\"/><rect x=\"75\" y=\"55\" width=\"14\" height=\"45\" fill=\"#3b82f6\"/><rect x=\"95\" y=\"55\" width=\"14\" height=\"45\" fill=\"#3b82f6\"/><rect x=\"115\" y=\"55\" width=\"14\" height=\"45\" fill=\"#3b82f6\"/><line x1=\"30\" y1=\"100\" x2=\"135\" y2=\"100\" stroke=\"#2a2f3f\"/><text x=\"255\" y=\"34\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">偏り（エントロピー小）</text><rect x=\"210\" y=\"95\" width=\"14\" height=\"5\" fill=\"#c9a04a\"/><rect x=\"230\" y=\"20\" width=\"14\" height=\"80\" fill=\"#c9a04a\"/><rect x=\"250\" y=\"98\" width=\"14\" height=\"2\" fill=\"#c9a04a\"/><rect x=\"270\" y=\"99\" width=\"14\" height=\"1\" fill=\"#c9a04a\"/><rect x=\"290\" y=\"99\" width=\"14\" height=\"1\" fill=\"#c9a04a\"/><line x1=\"205\" y1=\"100\" x2=\"310\" y2=\"100\" stroke=\"#2a2f3f\"/></svg>"}'),

  ('g-kentei-k-q10', '8. AIに必要な数理・統計知識',
   '「本当の確率分布」と「モデルが予測した確率分布」の2つを比べて、どれだけ隔たりがあるかを数値で表す指標はどれか。この値は2つの分布が完全に一致するときに0になる。',
   NULL::text,
   '["KLダイバージェンス（カルバック・ライブラー情報量）", "分散", "共分散", "コサイン類似度"]',
   0, '[0]', 'single',
   '{"asked":"2つの確率分布の隔たりを数値化する指標を選ぶ問題。","why_asked":"交差エントロピー損失の背景にある「分布同士の隔たり」という考え方を、統計・情報理論の側から問う論点。","kid":"KLダイバージェンスは「正解の確率分布」と「モデルが予測した確率分布」がどれだけズレているかを測る物差し。2つの分布がぴったり同じなら0になり、ズレが大きいほど値も大きくなる。分類モデルの学習では、このズレをできるだけ小さくするように重みを調整していく。","eg":"たとえるなら、本物の地図（正解の分布）と、自分が描いた地図（予測した分布）を重ねて、どれくらいズレているかを数値化するようなイメージ。ぴったり重なればズレは0。","terms":[["KLダイバージェンス","2つの確率分布の隔たりを表す指標。完全に一致すると0になる"],["交差エントロピー損失","KLダイバージェンスと関係が深い、分類モデルでよく使う誤差関数"]],"think":"「2つの確率分布を比べる」「ズレが0なら完全一致」という2つの性質がKLダイバージェンスを見分ける決め手。値の大きさそのものより、「2つの分布の隔たりを測るための指標である」という役割を押さえる。","vs":"コサイン類似度と混同しやすいが、コサイン類似度は2つのベクトルの向きの近さを測るもので、確率分布同士の隔たりを測る指標ではない。","opt":["正解。2つの確率分布の隔たりを表し、完全に一致すると0になる指標。","分散は1つのデータの散らばりの大きさを測る指標で、2つの分布同士を比べるものではない。","共分散は2つの数値データが一緒にどう動くかを測る指標で、確率分布同士の隔たりを測るものではない。","コサイン類似度は2つのベクトルの向きの近さを測る指標で、確率分布の隔たりを測るものではない。"]}'),

  ('g-kentei-k-q11', '8. AIに必要な数理・統計知識',
   '観測されたデータが最も起こりやすくなるように、モデルのパラメータ（例えば正規分布の平均や分散）を選び出す考え方を何と呼ぶか。',
   NULL::text,
   '["最尤推定（Maximum Likelihood Estimation）", "ベイズ更新", "最小二乗法", "交差検証"]',
   0, '[0]', 'single',
   '{"asked":"観測データが最も起こりやすくなるようにパラメータを選ぶ考え方の名前を問う問題。","why_asked":"多くの機械学習モデルのパラメータ推定の土台になる考え方で、名前と考え方の両方を知っているか問う。","kid":"最尤推定は「今手元にあるデータが、一番『それっぽく』起こるようなパラメータはどれか」を探すやり方。例えば、コインを10回投げて7回表が出たら、「表が出る確率は0.5より0.7に近い方が、このデータがより起こりやすい」と考えて、0.7に近い値を選ぶ、というイメージ。","eg":"たとえるなら、犯人が誰かを推理するとき、「この証拠（データ）が一番自然に説明できるのは誰か」を考えて、一番つじつまが合う人（パラメータ）を選ぶ探偵のようなもの。","terms":[["尤度","あるパラメータのもとで、観測データがどれだけ起こりやすいかを表す値"],["最尤推定","尤度が最大になるようにパラメータを選ぶ推定方法"]],"think":"「観測データが起こりやすい」という物差し（尤度）を基準にパラメータを選ぶ、という発想が最尤推定の核。手元のデータに最もよく合うパラメータを、確率の大きさで判断して選び出す。","vs":"最小二乗法と混同しやすいが、最小二乗法は予測値と実際の値の差（誤差）の2乗を最小にするという考え方で、確率（尤度）の大きさを基準にする最尤推定とは着眼点が異なる。正規分布を仮定した場合には両者が同じ結果になることが知られている。","opt":["正解。観測データが最も起こりやすくなるようにパラメータを選ぶ推定方法。","ベイズ更新はもともとの確率（事前確率）に新しい証拠を反映して確率を更新する考え方で、尤度の最大化だけを基準にするものではない。","最小二乗法は誤差の2乗の合計を最小にするようにパラメータを選ぶ方法で、尤度の大小を基準にする最尤推定とは着眼点が異なる。","交差検証はモデルの性能を評価するためにデータを分割して検証する手法で、パラメータの推定方法そのものではない。"]}'),

  ('g-kentei-k-q12', '8. AIに必要な数理・統計知識',
   'サイコロを1回振ったときの出目の平均は分からなくても、何千回も振って平均を取ると、その平均はサイコロの出目の理論上の平均（3.5）に近づいていく。この性質を何と呼ぶか。',
   NULL::text,
   '["大数の法則", "中心極限定理", "ベイズの定理", "标準誤差"]',
   0, '[0]', 'single',
   '{"asked":"試行回数を増やすほど標本平均が理論上の平均に近づいていく性質の名前を問う問題。","why_asked":"中心極限定理と名前も内容も混同されやすく、「何が近づくか」の違いを区別できるかを問う定番の論点。","kid":"大数の法則は「試行の回数を増やせば増やすほど、実際に観測した平均は、本当の平均（理論上の値）にどんどん近づいていく」という性質。サイコロを1回や2回振っただけでは平均3.5にはならないが、何千回も振り続ければ、平均はだんだん3.5に近づいていく。","eg":"たとえるなら、コインを10回投げただけでは表が7回出ることもあるけれど、1万回投げれば表の割合はほぼ50%に近づいていく、というイメージ。回数を重ねるほど、ブレが均されて本来の確率に近づく。","terms":[["大数の法則","試行回数を増やすほど、標本平均が理論上の平均（母平均）に近づいていく性質"],["標本平均","実際に観測したデータから計算した平均"]],"think":"「回数を増やすと、平均がある1つの値に近づいていく」というのが大数の法則の主張。近づいていく先は「理論上の平均（期待値）」であり、この法則自体は分布の形については何も述べていない点が、中心極限定理との違い。","vs":"中心極限定理と混同しやすいが、中心極限定理は「標本平均を何度も計算したときの、標本平均自体の分布の形が正規分布に近づく」という性質を述べたもので、大数の法則の「値そのものが近づく」という主張とは着眼点が違う。","opt":["正解。試行回数を増やすほど、標本平均が理論上の平均に近づいていく性質。","中心極限定理は標本平均の分布の形が正規分布に近づくという性質で、値そのものが近づく大数の法則とは着眼点が異なる。","ベイズの定理は事前確率に新しい証拠を反映して確率を更新する公式で、試行回数を増やす話とは異なる。","標準誤差は標本平均のばらつきの大きさを表す値で、平均が近づいていく性質そのものの名称ではない。"]}'),

  ('g-kentei-k-q13', '8. AIに必要な数理・統計知識',
   '母集団全体（例えば日本人全員）の平均身長そのものと、その一部を無作為に選んで測った標本の平均身長について、最も適切な説明はどれか。',
   NULL::text,
   '["標本平均は、標本の選び方によって値が変わりうる、母平均の推定値である", "標本平均は常に母平均とまったく同じ値になる", "母平均は、標本を何回か測り直せば必ず正確に求められる", "標本平均と母平均は無関係で、比較する意味がない"]',
   0, '[0]', 'single',
   '{"asked":"母平均と標本平均の関係、特に標本平均が推定値であるという性質を問う問題。","why_asked":"「標本から母集団を推定する」という推測統計の大前提を理解しているか、AI分野でも訓練データが母集団の一部にすぎないという文脈で重要な論点。","kid":"母平均は「全員をくまなく調べたときの本当の平均」で、普通は手に入らない。標本平均は「その一部だけを選んで調べた平均」で、選ぶ人によって少しずつ違う値になる。標本平均はあくまで母平均の「見積もり」であって、ぴったり同じとは限らない。","eg":"たとえるなら、鍋の味見（標本平均）をして鍋全体の味（母平均）を推測するようなもの。一口だけ味見しても、たまたま濃い部分をすくえば実際より濃く感じることがある。","terms":[["母平均","調べたい集団全員（母集団）についての本当の平均"],["標本平均","母集団の一部（標本）だけを調べて計算した平均。選び方によって値がぶれる"]],"think":"「全員は調べられないから、一部を選んで全体を見積もる」というのが推測統計の出発点。標本平均は母平均そのものではなく、あくまで母平均を推定するための手がかりであり、標本の選び方によって値がぶれる、という不確かさを持つ。","vs":"「標本を十分大きく取れば、標本平均は母平均に近づいていく」という大数の法則の性質と、「標本平均が母平均とぴったり一致するとは限らない」という不確かさは、矛盾せず両立する点に注意。","opt":["正解。標本平均は選び方によって変わりうる、母平均を推定するための値。","標本の選び方によって標本平均は変わりうるため、母平均と常に完全に一致するとは限らない。","標本を測り直しても標本平均が変わるだけで、母平均そのものを完全かつ正確に求められるとは限らない。","標本平均は母平均を推定するために使われるものであり、両者は密接に関係しているため、無関係とは言えない。"]}'),

  ('g-kentei-k-q14', '8. AIに必要な数理・統計知識',
   'あるテストの平均点は60点、標準偏差は10点だった。このとき、80点を取った人の得点を標準化（z値に変換）すると、いくつになるか。',
   NULL::text,
   '["2", "20", "0.2", "8"]',
   0, '[0]', 'single',
   '{"asked":"平均と標準偏差から、ある得点を標準化（z値）に変換する計算問題。","why_asked":"標準化の式z=(x-平均)÷標準偏差を、実際の数値に当てはめて計算できるかを確認する定番の計算問題。","kid":"標準化（z値）は「平均からどれだけ離れているかを、標準偏差を単位にして測り直したもの」。80点は平均60点から20点離れている。この20点が、標準偏差10点のちょうど2個分にあたるので、z値は2になる。","eg":"たとえるなら、平均からのズレを「標準偏差というものさし」で測り直すイメージ。ものさし1本が10点なら、20点のズレはものさし2本分、というのがz値2の意味。","terms":[["標準化（z値）","(得点-平均)÷標準偏差で計算される、平均からのズレを標準偏差の単位で表した値"],["標準偏差","データが平均からどれくらい離れて散らばっているかを表す値。ここでは10点"]],"calc":{"steps":["問題: 得点=80、平均=60、標準偏差=10のとき、z値を求める","ステップ1: まず平均からのズレを計算する。80 − 60 = 20","ステップ2: そのズレを標準偏差で割る。20 ÷ 10","ステップ3: 割り算する。20 ÷ 10 = 2","答え: z値は2"],"formula":"z = (x − 平均) ÷ 標準偏差 = (80 − 60) ÷ 10 = 20 ÷ 10 = 2"},"think":"標準化の式は「平均からの差」を「標準偏差」で割るだけの単純な計算。差を求める引き算と、その差を標準偏差の単位に直す割り算の、2ステップだけで解ける。","vs":"平均からの差（20点）をそのままz値と勘違いしないよう注意。z値は差をさらに標準偏差で割って、「標準偏差何個分か」という単位に変換した値である。","opt":["正解。(80-60)÷10=20÷10=2。","平均からの差である20点をそのままz値としてしまった誤り。標準偏差で割る手順が抜けている。","20÷10=2を、桁を1つ間違えて0.2としてしまった誤り。","標準偏差の値10をそのまま8点と間違えて計算したような、標準化の式に沿わない値。"]}'),

  ('g-kentei-k-q15', '8. AIに必要な数理・統計知識',
   '2つの数値データが「一方が大きくなるともう一方も大きくなる傾向があるか」「一方が大きくなるともう一方は小さくなる傾向があるか」を、符号（プラス・マイナス）で表す統計量はどれか。相関係数のもとになる値でもある。',
   NULL::text,
   '["共分散", "分散", "標準偏差", "中央値"]',
   0, '[0]', 'single',
   '{"asked":"2つのデータの一緒の動き方を符号で表す統計量を選ぶ問題。","why_asked":"相関係数の計算式の中身（共分散を標準偏差で割ったもの）を理解しているか問う、相関係数の一歩手前の論点。","kid":"共分散は「2つのデータが同じ方向に動く傾向があるか、逆方向に動く傾向があるか」をプラス・マイナスの符号で表す値。片方が大きいときもう片方も大きい傾向があればプラス、片方が大きいときもう片方は小さい傾向があればマイナスになる。","eg":"たとえるなら、気温とアイスの売上のように「暑い日ほど売上が伸びる」関係ならプラスの共分散、気温と鍋の売上のように「暑い日ほど売上が落ちる」関係ならマイナスの共分散、というイメージ。","terms":[["共分散","2つのデータが同じ方向に動く傾向があればプラス、逆方向ならマイナスになる統計量"],["相関係数","共分散を、それぞれの標準偏差で割って-1〜1の範囲に基準化した値"]],"think":"共分散は「2つのデータの動きの向きの関係」を符号で表すが、単位やスケールの影響を受けるため、値の大きさそのものでは「関係の強さ」を比較しにくい。そこで共分散を2つの標準偏差で割って-1〜1に基準化したものが相関係数、という順序で理解する。","vs":"分散と混同しやすいが、分散は1つのデータだけの散らばりを表す値であるのに対し、共分散は2つのデータの一緒の動き方を表す値で、扱う対象のデータの数が違う。","opt":["正解。2つのデータが同じ方向に動くか逆方向に動くかを符号で表し、相関係数のもとになる統計量。","分散は1つのデータの散らばりの大きさを表す値で、2つのデータの関係を表すものではない。","標準偏差は分散の平方根で、1つのデータの散らばりを表す値であり、2つのデータの関係を表すものではない。","中央値はデータを並べたときの真ん中の値で、2つのデータの一緒の動き方とは無関係な代表値。"]}'),

  ('g-kentei-k-q16', '8. AIに必要な数理・統計知識',
   '2つの独立な（互いに影響し合わない）確率変数XとYがあるとき、その和X+Yの分散について、最も適切な説明はどれか。',
   NULL::text,
   '["Xの分散とYの分散を足し合わせたものになる", "Xの分散とYの分散を掛け合わせたものになる", "XとYが独立なら、和の分散は常に0になる", "和の分散は、必ずXの分散とYの分散のどちらか大きい方と同じになる"]',
   0, '[0]', 'single',
   '{"asked":"独立な2つの確率変数の和の分散が、それぞれの分散とどう関係するかを問う問題。","why_asked":"分散の加法性は、標本平均のばらつき（標準誤差）や機械学習のノイズの扱いを理解する土台になる性質。","kid":"XとYが互いに関係なくバラバラに動く（独立な）ときは、X+Yの散らばり具合（分散）は、Xの散らばりとYの散らばりを単純に足し算したものになる。この性質を「分散の加法性」と呼ぶ。","eg":"たとえるなら、サイコロを2つ振って出た目の合計のばらつきは、1つのサイコロのばらつきを2つ分足し合わせたものになる、というイメージ。互いに影響しない者同士のばらつきは、足し算で積み上がっていく。","terms":[["分散の加法性","独立な確率変数の和の分散は、それぞれの分散の和に等しくなる性質"],["独立","一方の値がもう一方の値に影響を与えない関係"]],"think":"「独立」という条件がこの性質のポイント。もし2つの変数が互いに関係し合っている（独立でない）場合は、共分散の項が加わってこのシンプルな足し算の関係は成り立たなくなる。今回は独立という条件があるため、単純にVar(X)+Var(Y)で求められる。","vs":"標準偏差の加法性と混同しやすいが、分散は足し算できても、標準偏差（分散の平方根）はそのまま単純には足し算できない点に注意。","opt":["正解。独立な確率変数の和の分散は、それぞれの分散を足し合わせたものになる。","分散同士を掛け合わせるという操作は、分散の加法性の定義とは異なる。","独立であっても、それぞれの確率変数自体にばらつきがあれば、和の分散が0になるとは限らない。","和の分散はそれぞれの分散を足し合わせた値になり、どちらか大きい方とだけ一致するとは限らない。"]}'),

  ('g-kentei-k-q17', '8. AIに必要な数理・統計知識',
   '確率変数XとYについて、E[X+Y]（X+Yの期待値）は、E[X]とE[Y]（それぞれの期待値）とどのような関係にあるか。XとYが独立かどうかにかかわらず成り立つ性質として、最も適切なものを選べ。',
   NULL::text,
   '["E[X+Y]は、E[X]とE[Y]を足し合わせたものに等しい", "E[X+Y]は、XとYが独立なときに限り、E[X]とE[Y]を足し合わせたものに等しい", "E[X+Y]は、E[X]とE[Y]を掛け合わせたものに等しい", "E[X+Y]は、E[X]とE[Y]のうち大きい方の値に等しい"]',
   0, '[0]', 'single',
   '{"asked":"確率変数の和の期待値が、それぞれの期待値とどう関係するかを問う問題。","why_asked":"「期待値の線形性」は独立性を仮定せずに常に成り立つという、分散の加法性との対比で理解すべき重要な性質。","kid":"期待値は「平均して見込まれる値」のことで、X+Yの期待値は、Xの期待値とYの期待値を単純に足し算したものに、いつでも一致する。これはXとYが互いに関係し合っていても、いなくても変わらず成り立つ、とても使いやすい性質。","eg":"たとえるなら、サイコロAとサイコロBを振ったときの出目の合計の「平均して見込まれる値」は、サイコロAだけの平均（3.5）とサイコロBだけの平均（3.5）を足した7になる。2つのサイコロがどんな関係にあっても、この足し算はいつでも成り立つ。","terms":[["期待値の線形性","確率変数の和の期待値は、それぞれの期待値の和にいつでも等しくなる性質"],["独立性を仮定しない","期待値の線形性は、変数同士が独立かどうかに関係なく成り立つ点が分散の加法性と違う"]],"think":"分散の加法性は「独立」という条件が必要だったが、期待値の線形性は条件なしにいつでも成り立つ、という違いを対比で覚えておく。この性質のおかげで、複雑な確率変数の期待値も、単純な部分の期待値の足し算に分解して計算できる。","vs":"分散の加法性と混同しやすいが、分散の和が成り立つには「独立」という条件が必要なのに対し、期待値の和は独立かどうかに関係なく常に成り立つ点が大きく違う。","opt":["正解。E[X+Y]=E[X]+E[Y]は、XとYが独立かどうかに関係なく常に成り立つ。","期待値の線形性は独立性を仮定しなくても常に成り立つ性質であり、独立なときに限るという条件は不要。","期待値同士を掛け合わせる操作は、和の期待値の性質とは異なる計算。","期待値の和はそれぞれの期待値を足し合わせた値になり、大きい方とだけ一致するとは限らない。"]}'),

  ('g-kentei-k-q18', '8. AIに必要な数理・統計知識',
   '2つのベクトルの対応する成分同士を掛け算し、それを全部足し合わせて1つの数値にする計算を何と呼ぶか。ニューラルネットワークの層の計算（重みと入力の掛け算）でも使われる基本演算である。',
   NULL::text,
   '["内積（ドット積）", "外積", "転置", "ノルム"]',
   0, '[0]', 'single',
   '{"asked":"2つのベクトルの成分同士を掛けて足し合わせる基本演算の名前を問う問題。","why_asked":"ニューラルネットワークの全結合層の計算そのものが内積であり、線形代数の中でも最も頻出の基本演算。","kid":"内積は「2つのベクトルの、同じ順番の数字同士を掛け算して、その結果を全部足す」という計算。例えばベクトル(1,2)と(3,4)の内積は、1×3と2×4を計算してから足し合わせて、3+8=11になる。","eg":"たとえるなら、買い物カゴの中の商品の個数のベクトルと、それぞれの値段のベクトルを用意して、個数×値段を商品ごとに計算してから全部足し合わせると、合計金額が出る。この「掛けてから全部足す」計算が内積のイメージ。","terms":[["内積（ドット積）","2つのベクトルの対応する成分を掛け算し、その総和を取る計算"],["成分","ベクトルを構成する1つ1つの数字"]],"think":"「対応する成分同士を掛ける」「その結果を全部足す」という2つの操作の組み合わせが内積。ニューラルネットワークの層では、入力ベクトルと重みベクトルの内積を計算し、それにバイアスを足すことで1つのノードの出力が決まる。","vs":"外積と混同しやすいが、外積は3次元ベクトル同士から新しいベクトル（向きを持つ量）を作る演算で、内積のように1つの数値（スカラー）になる演算とは結果の種類が異なる。","opt":["正解。2つのベクトルの対応する成分を掛け算し、その総和を取る計算。","外積は主に3次元ベクトル同士から新しいベクトルを作る演算で、1つの数値になる内積とは結果の種類が異なる。","転置は行列やベクトルの行と列を入れ替える操作で、2つのベクトルから1つの数値を作る計算ではない。","ノルムは1つのベクトルの大きさ（長さ）を測る値で、2つのベクトルを組み合わせる内積とは対象が異なる。"]}'),

  ('g-kentei-k-q19', '8. AIに必要な数理・統計知識',
   'ベクトルの「大きさ（長さ）」を測る指標のうち、各成分の絶対値をそのまま足し合わせるものと、各成分を2乗してから足し合わせ、最後に平方根を取るものの組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["L1ノルムは絶対値の和、L2ノルムは2乗和の平方根で計算される", "L1ノルムは2乗和の平方根、L2ノルムは絶対値の和で計算される", "L1ノルムとL2ノルムは、どちらも成分の単純な合計（絶対値も2乗もしない）で計算される", "L1ノルムとL2ノルムに違いはなく、同じ計算方法を指す別名にすぎない"]',
   0, '[0]', 'single',
   '{"asked":"L1ノルムとL2ノルムそれぞれの計算方法を区別する問題。","why_asked":"L1正則化・L2正則化の名前の由来になっている「ベクトルの大きさの測り方の違い」を、数理の側からきちんと理解しているか問う。","kid":"ベクトルの「大きさ」の測り方にはいくつか流儀がある。L1ノルムは「各成分の絶対値をそのまま足し算する」測り方。L2ノルムは、私たちが普段使う「まっすぐの距離（三平方の定理）」と同じで、「各成分を2乗して、足してから、最後に平方根を取る」測り方。","eg":"たとえるなら、L1ノルムは「東に3ブロック、北に4ブロック」歩いた道のり（3+4=7ブロック）を測るイメージ、L2ノルムは地図上を斜めに突っ切ったときの直線距離（3²+4²の平方根＝5）を測るイメージ。同じ移動でも測り方によって数字が変わる。","terms":[["L1ノルム","各成分の絶対値をそのまま足し合わせて求めるベクトルの大きさ"],["L2ノルム","各成分を2乗して足し、平方根を取って求めるベクトルの大きさ。通常の「直線距離」に対応する"]],"think":"「絶対値のまま足すか」「2乗してから足して平方根を取るか」という計算手順の違いでL1とL2を区別する。L2ノルムは中学校で習う三平方の定理（直線距離）と同じ計算になっている点を手がかりにすると覚えやすい。","vs":"L1正則化・L2正則化と混同しやすいが、正則化はこのノルムを損失関数にペナルティとして加える手法の名前であり、ノルムそのものはあくまで「ベクトルの大きさを測る計算方法」を指す。","opt":["正解。L1ノルムは絶対値の和、L2ノルムは2乗和の平方根で、ベクトルの大きさを測る。","L1とL2の計算方法が入れ替わっており、説明が逆になっている。","絶対値も2乗も取らない単純な合計では、マイナスの成分がプラスの成分と打ち消し合ってしまい、大きさを正しく測れない。","L1ノルムとL2ノルムは計算方法が異なり、同じ値になるとは限らないため、単なる別名ではない。"]}'),

  ('g-kentei-k-q20', '8. AIに必要な数理・統計知識',
   '行列の「行」と「列」を入れ替える操作を何と呼ぶか。ニューラルネットワークの逆伝播の計算などでもよく登場する基本操作である。',
   NULL::text,
   '["転置（Transpose）", "逆行列", "固有分解", "正規化"]',
   0, '[0]', 'single',
   '{"asked":"行列の行と列を入れ替える基本操作の名前を問う問題。","why_asked":"逆伝播の勾配計算などで頻出する基本操作で、名前と操作の中身を対応づけて覚えているか問う。","kid":"転置は、行列を「右斜め上から左下に伸びる対角線」を軸にして、行と列をまるごと入れ替える操作。1行目に並んでいた数字が1列目に並び直す、というイメージ。","eg":"たとえるなら、横書きの座席表（行が学年、列が組）を、縦書きの座席表（行が組、列が学年）に書き直すようなもの。中身の数字（生徒の名前）は変わらず、並べ方の向きだけが変わる。","terms":[["転置","行列の行と列を入れ替える操作。記号ではAの右上に小さくTを付けてA^Tと書く"],["行と列","行は横並びの数字の並び、列は縦並びの数字の並び"]],"think":"「行と列を入れ替えるだけ」というシンプルな操作だが、行列の掛け算ができるかどうか（サイズが合うか）を調整するために欠かせない。逆伝播の計算式でも、重み行列を転置してから掛け算する場面がよく出てくる。","vs":"逆行列と混同しやすいが、逆行列はある行列と掛け合わせると単位行列になるような、割り算に相当する特別な行列を求める操作で、単に行と列を入れ替えるだけの転置とはまったく異なる計算。","opt":["正解。行列の行と列を入れ替える操作。","逆行列は掛け合わせると単位行列になる特別な行列を求める操作で、転置とは異なる計算。","固有分解は行列を固有値と固有ベクトルの組み合わせに分解する操作で、単純な行と列の入れ替えではない。","正規化はデータの値の範囲やスケールをそろえる操作で、行列の行と列を入れ替える操作とは異なる。"]}'),

  ('g-kentei-k-q21', '8. AIに必要な数理・統計知識',
   'ある行列による変換（回転や引き伸ばし）を受けても、向きが変わらず、長さだけが変わるような特別なベクトルを何と呼ぶか。主成分分析（PCA）でデータの分散が最大になる方向を求める際にも使われる。',
   NULL::text,
   '["固有ベクトル（Eigenvector）", "単位ベクトル", "法線ベクトル", "ゼロベクトル"]',
   0, '[0]', 'single',
   '{"asked":"行列による変換で向きが変わらない特別なベクトルの名前を問う問題。","why_asked":"PCA（主成分分析）の数理的な土台であり、G検定の次元削減の理解を一段深める論点。","kid":"多くのベクトルは、行列で変換すると向きも長さも変わってしまう。でも中には、変換しても「向きだけは変わらず、長さだけが伸び縮みする」特別なベクトルがある。これが固有ベクトル。PCAでは、データの散らばり方（分散共分散行列）に対するこの固有ベクトルの向きを探すことで、「データが一番広がっている方向」を見つけ出している。","eg":"たとえるなら、生地を斜めに引き伸ばしても、ある特定の方向の糸目だけは向きを保ったまま、ただ長く伸びるだけになる、というイメージ。その特別な方向の糸目が固有ベクトル。","terms":[["固有ベクトル","ある行列で変換しても向きが変わらない特別なベクトル"],["固有値","固有ベクトルが変換によって何倍に伸び縮みするかを表す数値"]],"think":"「変換しても向きが変わらない」という性質が固有ベクトルの本質。PCAでは、データのばらつき方を表す分散共分散行列に対してこの固有ベクトルを求め、その向きを「データが最も広がっている軸（主成分）」として使う。","vs":"単位ベクトルと混同しやすいが、単位ベクトルは単に長さが1のベクトルを指す言葉であり、変換で向きが変わらないという固有ベクトルの性質とは無関係の概念。","opt":["正解。行列で変換しても向きが変わらない特別なベクトル。PCAの主成分の方向を求めるのに使われる。","単位ベクトルは長さが1のベクトルというだけの意味で、変換で向きが変わらないという性質とは無関係。","法線ベクトルは平面に垂直な向きを持つベクトルのことで、行列変換での向きの不変性とは異なる概念。","ゼロベクトルはすべての成分が0のベクトルで、向きという概念自体を持たないため固有ベクトルの説明には当たらない。"],"viz":"<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">固有ベクトル：変換しても向きは同じ</text><line x1=\"170\" y1=\"30\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"70\" y1=\"80\" x2=\"270\" y2=\"80\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"170\" y1=\"80\" x2=\"220\" y2=\"50\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#a1)\"/><text x=\"228\" y=\"47\" font-size=\"9\" fill=\"#8892a4\">元のベクトル</text><line x1=\"170\" y1=\"80\" x2=\"250\" y2=\"20\" stroke=\"#3b82f6\" stroke-width=\"2\" marker-end=\"url(#a2)\"/><text x=\"252\" y=\"18\" font-size=\"9\" fill=\"#3b82f6\">変換後（同じ向き、伸びた）</text><line x1=\"170\" y1=\"80\" x2=\"200\" y2=\"65\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#a1)\"/><text x=\"130\" y=\"63\" font-size=\"9\" fill=\"#8892a4\">別のベクトル</text><line x1=\"170\" y1=\"80\" x2=\"140\" y2=\"110\" stroke=\"#c9a04a\" stroke-width=\"2\" marker-end=\"url(#a3)\"/><text x=\"90\" y=\"122\" font-size=\"9\" fill=\"#c9a04a\">変換後（向きが変わる）</text><defs><marker id=\"a1\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker><marker id=\"a2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#3b82f6\"/></marker><marker id=\"a3\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#c9a04a\"/></marker></defs></svg>"}'),

  ('g-kentei-k-q22', '8. AIに必要な数理・統計知識',
   '固有ベクトルが変換によって「何倍」に伸び縮みするかを表す数値を何と呼ぶか。',
   NULL::text,
   '["固有値（Eigenvalue）", "固有ベクトル", "行列式", "分散"]',
   0, '[0]', 'single',
   '{"asked":"固有ベクトルの伸び縮みの倍率を表す数値の名前を問う問題。","why_asked":"固有ベクトルとセットで覚える固有値の役割（PCAでは分散の大きさに対応する）を区別できるか問う。","kid":"固有ベクトルは「向きが変わらない特別な矢印」だったが、その矢印の長さが変換によって何倍になるかを表す数字が固有値。固有値が大きいほど、その方向にデータが大きく引き伸ばされる、つまりその方向にデータが大きくばらついている、という意味になる。","eg":"たとえるなら、ゴムひもをある方向にだけ強く引っ張ると、その方向のゴムひもは大きく伸びる。この「何倍に伸びたか」を表す数字が固有値、伸びた方向そのものが固有ベクトル、というペアで覚える。","terms":[["固有値","固有ベクトルが変換によって何倍に伸び縮みするかを表す数値"],["固有ベクトル","変換しても向きが変わらない特別なベクトル"]],"think":"固有値と固有ベクトルは必ずペアで登場する。「どの向きが変わらないか」を教えてくれるのが固有ベクトル、「その向きにどれだけ影響が大きいか（伸び縮みの倍率）」を教えてくれるのが固有値、という役割分担で覚える。PCAでは固有値が大きい方向ほど、データの分散が大きい主成分として選ばれる。","vs":"固有ベクトルと混同しやすいが、固有ベクトルは「向き」を表す矢印そのものであるのに対し、固有値は「その矢印がどれだけ伸び縮みするか」を表す1つの数値である点が違う。","opt":["正解。固有ベクトルが変換によって何倍に伸び縮みするかを表す数値。","固有ベクトルは向きを表す矢印そのものであり、伸び縮みの倍率を表す数値ではない。","行列式は行列全体がどれだけ空間を拡大・縮小するかを表す1つの数値で、特定の固有ベクトルの伸び縮みの倍率とは異なる概念。","分散はデータの散らばりの大きさを表す統計量で、固有ベクトルの伸び縮みの倍率そのものを直接指す言葉ではない。"]}'),

  ('g-kentei-k-q23', '8. AIに必要な数理・統計知識',
   'ある関数のグラフ上のある点における「接線の傾き」、つまりその点で入力をほんの少しだけ増やしたときに出力がどれくらい変化するかの割合を表すものを何と呼ぶか。',
   NULL::text,
   '["微分（導関数の値）", "積分", "期待値", "分散"]',
   0, '[0]', 'single',
   '{"asked":"関数上のある点での接線の傾き（変化の割合）を表す概念の名前を問う問題。","why_asked":"誤差逆伝播法や勾配降下法の土台になる「微分」そのものの意味を、公式ではなく直感で理解しているか問う。","kid":"微分は「ある1点で、入力をほんの少しだけ増やしたときに、出力がどれくらい増えるか（または減るか）」を表す値。グラフで言うと、その点にぴったり触れる接線を引いたときの、その線の傾きにあたる。","eg":"たとえるなら、山道を歩いているときの「今立っている場所の坂の急さ」を表す数字。平らな場所なら傾きは0に近く、急な上り坂なら傾きは大きなプラスの値になる。","terms":[["微分","ある点での関数の変化の割合（接線の傾き）を表す値"],["接線","グラフのある1点にだけぴったり触れる直線"]],"think":"「1点における、入力の微小な変化に対する出力の変化の割合」が微分の本質。ニューラルネットワークの学習では、この微分（勾配）を使って「重みをどちらの方向に、どれくらい動かせば誤差が減るか」を計算している。","vs":"積分と混同しやすいが、積分はグラフの下の面積を求める操作で、微分（傾きを求める操作）とは逆の関係にある別の演算。","opt":["正解。関数上のある点における接線の傾き、つまり変化の割合を表す。","積分はグラフの下の面積を求める演算で、傾きを求める微分とは逆向きの操作。","期待値は確率変数の平均して見込まれる値を表すもので、関数の傾きとは異なる概念。","分散はデータの散らばりの大きさを表す統計量で、関数の傾きとは異なる概念。"]}'),

  ('g-kentei-k-q24', '8. AIに必要な数理・統計知識',
   '複数の変数を持つ関数について、「1つの変数だけに注目し、他の変数はすべて固定した（動かさない）状態で」その変数についてだけ微分することを何と呼ぶか。',
   NULL::text,
   '["偏微分", "積分", "全微分の総和", "重回帰"]',
   0, '[0]', 'single',
   '{"asked":"複数の変数を持つ関数で、1つの変数だけに注目して微分する操作の名前を問う問題。","why_asked":"ニューラルネットワークの重みは大量にあり、それぞれの重みについて偏微分して勾配を求める、という誤差逆伝播法の土台の理解を問う。","kid":"ニューラルネットワークの誤差は、重みという変数がたくさんある関数として表せる。偏微分は、その中の「1つの重みだけ」に注目して、「他の重みは全部そのまま動かさずに固定して」、その1つの重みを動かしたら誤差がどう変わるかを調べる計算。","eg":"たとえるなら、たくさんの蛇口（重み）がある水槽で、「1つの蛇口だけひねったら水位がどう変わるか」を、他の蛇口はそのままの状態で確かめるようなイメージ。全部の蛇口を同時にひねったらどう変わるかは、また別の計算になる。","terms":[["偏微分","複数の変数のうち1つだけに注目し、他を固定して行う微分"],["勾配","すべての変数について偏微分した値を並べたもの。誤差逆伝播法で使われる"]],"think":"「他の変数を固定する」という条件が偏微分のポイント。ニューラルネットワークには重みが大量にあるため、誤差をそれぞれの重みについて偏微分し、その結果を並べた「勾配」を使って、どの重みをどちらにどれだけ動かせば誤差が減るかを一括で求めている。","vs":"通常の微分と混同しやすいが、通常の微分は変数が1つしかない関数を対象にするのに対し、偏微分は変数が複数ある関数の中で、特定の1つの変数だけに注目する点が違う。","opt":["正解。複数の変数のうち1つだけに注目し、他の変数は固定して行う微分。","積分はグラフの下の面積を求める演算で、変数を固定して微分する偏微分とは異なる操作。","全微分はすべての変数の変化を同時に考える別の考え方で、1つの変数だけに注目する偏微分とは異なる。","重回帰は複数の説明変数から1つの目的変数を予測する統計モデルの手法で、偏微分という計算操作そのものではない。"]}'),

  ('g-kentei-k-q25', '8. AIに必要な数理・統計知識',
   'y = f(g(x)) のように、ある関数の中に別の関数が入れ子になっている「合成関数」を微分するとき、「外側の関数の微分」と「内側の関数の微分」を掛け合わせて計算するというルールを何と呼ぶか。',
   NULL::text,
   '["連鎖律（Chain Rule）", "積の法則", "商の法則", "線形性"]',
   0, '[0]', 'single',
   '{"asked":"合成関数の微分を「外側×内側」の掛け算で計算するルールの名前を問う問題。","why_asked":"誤差逆伝播法は、層を重ねた合成関数の連鎖律そのものであり、G検定でも仕組みの土台として理解が問われる。","kid":"ニューラルネットワークは、層を何層も重ねた「関数の中に関数が入った」構造をしている。連鎖律は、こういう入れ子の関数を微分するとき、「一番外側の変化の割合」と「一番内側の変化の割合」を、順番に掛け算していけば、全体の変化の割合が求まる、というルール。","eg":"たとえるなら、歯車が3つつながった機械で、1つ目の歯車を1回転させると2つ目が3回転し、2つ目を1回転させると3つ目が2回転するとき、1つ目を1回転させたときの3つ目の回転数は、3×2=6回転というふうに、それぞれの倍率を掛け算していけば求まる。連鎖律もこれと同じ「掛け算でつなぐ」考え方。","terms":[["連鎖律","合成関数の微分を、外側の関数の微分と内側の関数の微分の掛け算で求めるルール"],["誤差逆伝播法","連鎖律を使って、出力層の誤差を入力層側の重みまで順番にさかのぼって伝える手法"]],"think":"ニューラルネットワークの各層は「前の層の出力を受け取って、次の層に渡す」という合成関数になっている。連鎖律を使うことで、一番奥の層（入力に近い層）の重みについての勾配も、出力層側から順に「掛け算をつなげていく」ことで効率よく計算できる。これが誤差逆伝播法の数学的な土台。","vs":"積の法則と混同しやすいが、積の法則は「2つの関数を掛け算したもの」を微分するときのルールであり、「関数の中に関数が入っている（入れ子になっている）」合成関数を微分する連鎖律とは対象にしている関数の形が違う。","opt":["正解。合成関数の微分を、外側と内側それぞれの微分の掛け算で求めるルール。誤差逆伝播法の土台。","積の法則は2つの関数の掛け算を微分するルールで、入れ子になった合成関数を対象にする連鎖律とは異なる。","商の法則は2つの関数の割り算を微分するルールで、合成関数の微分とは異なる規則。","線形性は微分において定数倍や和がそのまま外に出せる性質のことで、入れ子の関数をつなげる連鎖律とは異なる性質。"],"viz":"<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">連鎖律：微分を掛け算でつなぐ</text><rect x=\"20\" y=\"45\" width=\"70\" height=\"34\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"55\" y=\"66\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">内側 g(x)</text><rect x=\"135\" y=\"45\" width=\"70\" height=\"34\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"66\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">外側 f( )</text><rect x=\"250\" y=\"45\" width=\"70\" height=\"34\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"285\" y=\"66\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">出力 y</text><line x1=\"90\" y1=\"62\" x2=\"133\" y2=\"62\" stroke=\"#8892a4\" marker-end=\"url(#c1)\"/><line x1=\"205\" y1=\"62\" x2=\"248\" y2=\"62\" stroke=\"#8892a4\" marker-end=\"url(#c1)\"/><text x=\"111\" y=\"94\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">g′(x)</text><text x=\"227\" y=\"94\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">f′(g(x))</text><text x=\"170\" y=\"112\" text-anchor=\"middle\" font-size=\"10\" fill=\"#6ab08d\">dy/dx = f′(g(x)) × g′(x)　← 掛け算でつなぐ</text><defs><marker id=\"c1\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs></svg>"}'),

  ('g-kentei-k-q26', '8. AIに必要な数理・統計知識',
   'コインを1回投げる試行の期待値は0.5（表を1、裏を0とした場合）である。このコインを100回投げたときの表が出る回数の期待値はいくつになるか。',
   NULL::text,
   '["50回", "0.5回", "100回", "5回"]',
   0, '[0]', 'single',
   '{"asked":"1回あたりの期待値から、複数回試行したときの合計の期待値を計算する問題。","why_asked":"期待値の線形性（E[X1+X2+...+Xn]=E[X1]+E[X2]+...+E[Xn]）を、具体的な数値で確認する計算問題。","kid":"1回のコイン投げの期待値が0.5ということは、100回投げたときの合計の期待値は、期待値の線形性から「0.5を100回分足し合わせたもの」になる。0.5×100を計算すればよい。","eg":"たとえるなら、1回のくじで平均0.5個の景品がもらえるとしたら、100回くじを引けば平均して0.5×100=50個の景品がもらえると見込める、というイメージ。","terms":[["期待値の線形性","複数の確率変数の和の期待値は、それぞれの期待値の和に等しくなる性質"],["1回あたりの期待値","コインを1回投げたときに見込まれる表の出やすさを表す値。今回は0.5"]],"calc":{"steps":["問題: 1回あたりの期待値0.5を、100回分足し合わせる","ステップ1: 期待値の線形性より、100回分の合計の期待値は「1回あたりの期待値×100」で求まる","ステップ2: 数値を当てはめる。0.5 × 100","ステップ3: 掛け算する。0.5 × 100 = 50","答え: 50回"],"formula":"E[X1+X2+...+X100] = 100 × E[X1] = 100 × 0.5 = 50"},"think":"期待値の線形性を使えば、100個の確率変数の和の期待値を、1つ1つの期待値の和として計算できる。今回はすべて同じコインなので、0.5を100回分足す、つまり0.5×100という単純な掛け算になる。","vs":"1回あたりの期待値0.5をそのまま答えにしないよう注意。問われているのは「100回投げたときの合計」の期待値であり、1回分の期待値ではない。","opt":["正解。0.5×100=50回。","1回のコイン投げの期待値であり、100回分の合計の期待値ではない。","0.5×100を1桁間違えて100としてしまった計算の誤り。","0.5×100=50を、さらに10で割ってしまったような、期待値の線形性の計算式に沿わない値。"]}'),

  ('g-kentei-k-q27', '8. AIに必要な数理・統計知識',
   '複数の変数（例えば身長・体重・年齢）のデータについて、それぞれの変数同士の分散と共分散を、まとめて1つの行列にしたものを何と呼ぶか。対角線上の成分は各変数自身の分散、それ以外の成分は変数同士の共分散になる。',
   NULL::text,
   '["分散共分散行列", "相関行列", "混同行列", "単位行列"]',
   0, '[0]', 'single',
   '{"asked":"複数の変数の分散と共分散をまとめた行列の名前を問う問題。","why_asked":"PCA（主成分分析）は分散共分散行列の固有ベクトル・固有値を求める手法であり、次元削減の数理的な土台の理解を問う。","kid":"変数がたくさんあるとき、それぞれの変数自身の散らばり具合（分散）と、変数同士の一緒の動き方（共分散）を、まとめて表にしたものが分散共分散行列。表の対角線（左上から右下）には各変数自身の分散が並び、それ以外のマスにはペアごとの共分散が並ぶ。","eg":"たとえるなら、クラス全員の身長・体重・年齢について、「身長自身のばらつき」「体重自身のばらつき」「身長と体重が一緒にどう動くか」などを、1枚の表にまとめて一覧できるようにしたもの。","terms":[["分散共分散行列","複数の変数の分散（対角成分）と共分散（非対角成分）をまとめた行列"],["対角成分","行列の左上から右下に並ぶ、行番号と列番号が同じマスの成分"]],"think":"「対角成分は分散、非対角成分は共分散」という構造を押さえる。PCA（主成分分析）では、この分散共分散行列に対して固有値・固有ベクトルを求め、データが最も広がっている方向（主成分）を探し出す、という流れにつながる。","vs":"相関行列と混同しやすいが、相関行列は分散共分散行列の値をそれぞれの標準偏差で割って-1〜1に基準化したもので、分散共分散行列そのものとは値のスケールが異なる。","opt":["正解。対角成分に各変数の分散、非対角成分に変数同士の共分散が並ぶ行列。","相関行列は分散共分散行列を基準化して-1〜1の範囲にした行列で、分散共分散行列そのものとは異なる。","混同行列は分類モデルの予測と正解の当たり外れを集計した表で、分散や共分散をまとめたものではない。","単位行列は対角成分がすべて1、それ以外が0の特別な行列で、分散や共分散の値をまとめたものではない。"]}')

